(function(){if(!location.pathname.includes('/tools/events/register_cdo/eventid/23975'))return;function put(el,value){if(el&&el.textContent!==value)el.textContent=value;}function clean(){var body=document.getElementById('RegisterBody');if(!body)return;body.querySelectorAll('.reservation').forEach(function(row,index){put(row.querySelector('[id$="_index"]'),String(index+1));var el=row.querySelector('.g100, .float_right > .inline_block:not(.price-display)');if(!el)return;var v=el.textContent.trim();if(v.includes('Family'))put(el,'Adult group (up to 4)');else if(v.includes('Children')&&!v.includes('under'))put(el,'Children (ages 3–11)');else if(v.includes('Toddlers'))put(el,'Children under 3');});var tiers=['$36 · Challah for the table','$72 · Wine for the table','$180 · Help set the Shabbat table','$360 · Help host the dinner','$1,800 · Sponsor the evening'];tiers.forEach(function(label,i){put(document.querySelector('#label_input_33_'+i+' span'),label);});var label=Array.from(document.querySelectorAll('#AdditionalInformation label')).find(function(el){return el.textContent.trim()==='Sponsorship Opportunities';});put(label,'Add a sponsorship');}function start(){clean();var body=document.getElementById('RegisterBody');if(body){var pending=false;new MutationObserver(function(){if(!pending){pending=true;setTimeout(function(){pending=false;clean();},0);}}).observe(body,{childList:true,subtree:true});}setTimeout(clean,600);}if(document.readyState==='complete')start();else window.addEventListener('load',start);})();